const p=$json;
const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;
const expectedTags=$('LIBERAL — Consolidar etiquetas v1.13').first().json.tag_ids.map(Number).sort((a,b)=>a-b);
const actualTags=Array.isArray(p.tags)?p.tags.map(Number).sort((a,b)=>a-b):null;
if(String(p.slug??'')!==c.slug) throw new Error('LIBERAL slug no coincide.');
if(String(p?.meta?.liberalmx_editorial?.subtitle??'')!==String(c.subtitle??'')) throw new Error('LIBERAL subtítulo no coincide.');
if(String(p?.meta?.liberalmx_editorial?.photo_credit??'')!==String(c.images.hero_liberal.credit??'')) throw new Error('LIBERAL crédito de Hero no coincide.');
if(Number(p.author)!==Number(c.author_liberal.id)) throw new Error('LIBERAL autor no coincide.');
if(String(p?.title?.raw??'')!==c.title) throw new Error('LIBERAL título no coincide.');
if(!actualTags || JSON.stringify(actualTags)!==JSON.stringify(expectedTags)) throw new Error('LIBERAL etiquetas no coinciden.');
for(const [key,value] of [['rank_math_title',c.title],['rank_math_description',c.meta_description],['rank_math_focus_keyword',c.keywords_all]]) {
  if(String(p?.meta?.[key]??'')!==String(value??'')) throw new Error('LIBERAL SEO no coincide: '+key);
}
if(typeof p?.content?.raw!=='string' || p.content.raw!==c.gutenberg_enriquecido_final) throw new Error('LIBERAL Gutenberg no coincide en readback.');
const expectedFeatured=Number($('LIBERAL — Subir DESTACADA').first().json.id);
const expectedCat=Number($('LIBERAL — Resolver categoría').first().json.category_id);
const expectedHero=Number($('LIBERAL — Subir HERO').first().json.id);
if(!p?.id) throw new Error('LIBERAL readback no devolvió ID.');
if(String(p.status)!=='draft') throw new Error(`LIBERAL no está en draft antes de publicar. Estado: ${p.status}`);
if(!Number.isSafeInteger(expectedHero) || expectedHero < 1 || Number(p?.meta?.liberalmx_hero_media_id)!==expectedHero) throw new Error('LIBERAL HERO no coincide con el adjunto cargado.');
if(Number(p.featured_media)!==expectedFeatured) throw new Error(`LIBERAL featured_media no coincide. Esperado ${expectedFeatured}, recibido ${p.featured_media}.`);
if(!Array.isArray(p.categories)||!p.categories.map(Number).includes(expectedCat)) throw new Error('LIBERAL no confirmó la categoría esperada.');
const content=String(p?.content?.raw ?? p?.content?.rendered ?? '');
if(!content || content.includes('{{OPMX:HERO_LIBERAL}}')) throw new Error('LIBERAL conserva placeholder HERO o contenido vacío.');
return {json:{validated:true,post_id:Number(p.id)}};

const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;
const requested=String(c.categories?.liberal?.principal ?? c.category ?? '').trim();
if(!requested) throw new Error('El JSON MASTER no entregó la categoría principal para LIBERAL.');

const norm=s=>String(s??'')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/\s+/g,' ')
  .trim().toLocaleLowerCase('es-MX');

const rows=$input.all().map(i=>i.json).flatMap(x=>Array.isArray(x)?x:[x]);
const exact=rows.find(x=>norm(x.name)===norm(requested));

if(!exact?.id){
  const available=rows.map(x=>`${x.name??'(sin nombre)'} [slug ${x.slug??'?'} | ID ${x.id??'?'}]`).join(', ');
  throw new Error(`La categoría "${requested}" no existe como coincidencia exacta por nombre en El Liberal MX. Categorías recibidas de WordPress: ${available||'ninguna'}.`);
}
return [{json:{
  category_id:Number(exact.id),
  category_name:exact.name,
  category_slug:exact.slug??null,
  requested_category:requested,
  resolution:'EXACT_NORMALIZED_NAME_MATCH'
}}];
